method fib4(n: int) returns (result: int)
    requires n >= 0
    ensures result == fib4(n)
{
    var a := 0; // fib4(0)
    var b := 0; // fib4(1)
    var c := 2; // fib4(2)
    var d := 0; // fib4(3)

    if n == 0 {
        return a;
    } else if n == 1 {
        return b;
    } else if n == 2 {
        return c;
    } else if n == 3 {
        return d;
    }

    // For n >= 4
    var temp := 0;
    var i := 4;
    while i <= n
        invariant 4 <= i <= n + 1
        invariant a == fib4(i - 4) && b == fib4(i - 3) && c == fib4(i - 2) && d == fib4(i - 1)
        decreases n - i
    {
        temp := a + b + c + d; // fib4(i) = fib4(i-1) + fib4(i-2) + fib4(i-3) + fib4(i-4)
        a := b;
        b := c;
        c := d;
        d := temp;
        i := i + 1;
    }

    return d; // d now holds fib4(n)
}
